"use client";

import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import {
  Card,
  CardDescription,
  CardFooter,
  CardHeader,
} from "@/components/ui/card";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  useZodForm,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { LoadingButton } from "@/features/form/submit-button";
import { useI18n } from "@/i18n/provider";
import { authClient } from "@/lib/auth-client";
import { unwrapSafePromise } from "@/lib/promises";
import { useMutation } from "@tanstack/react-query";
import { Lock } from "lucide-react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { z } from "zod";

const EmailFormSchema = z.object({
  email: z.string().email(),
});

export function ForgetPasswordPage() {
  const router = useRouter();
  const { t } = useI18n();

  const emailForm = useZodForm({
    schema: EmailFormSchema,
  });

  const forgetPasswordMutation = useMutation({
    mutationFn: async (values: { email: string }) => {
      return unwrapSafePromise(
        authClient.requestPasswordReset({
          email: values.email,
          redirectTo: "/auth/reset-password",
        }),
      );
    },
    onError: (error) => {
      toast.error(error.message);
    },
    onSuccess: () => {
      router.push("/auth/verify");
    },
  });

  function onSubmitEmail(values: z.infer<typeof EmailFormSchema>) {
    forgetPasswordMutation.mutate(values);
  }

  return (
    <Card className="mx-auto w-full max-w-md lg:max-w-lg lg:p-6">
      <CardHeader>
        <div className="flex justify-center">
          <Avatar className="size-16">
            <AvatarFallback>
              <Lock />
            </AvatarFallback>
          </Avatar>
        </div>
        <CardHeader className="text-center">
          {t("auth.forgetPassword.title")}
        </CardHeader>

        <CardDescription className="text-center">
          {t("auth.forgetPassword.description")}
        </CardDescription>
      </CardHeader>

      <CardFooter className="border-t pt-6">
        <Form
          form={emailForm}
          onSubmit={onSubmitEmail}
          className="w-full space-y-4"
        >
          <FormField
            control={emailForm.control}
            name="email"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("auth.form.email")}</FormLabel>
                <FormControl>
                  <Input
                    placeholder={t("auth.form.emailPlaceholder")}
                    {...field}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <LoadingButton
            loading={forgetPasswordMutation.isPending}
            type="submit"
            className="w-full"
          >
            {t("auth.forgetPassword.submit")}
          </LoadingButton>
        </Form>
      </CardFooter>
    </Card>
  );
}

