  await page.waitForURL(/\/app/, { timeout: 10000 });

  // Clean up - delete the test user
  const user = await prisma.user.findUnique({
    where: { email: userData.email },
  });

  if (user) {
    await prisma.user.delete({
      where: { id: user.id },
    });
  }
});

